use googletest::matchers::eq;
use googletest::{expect_that, gtest};
#[gtest]
fn test_macros() {
    use macros::{CAST_CONST, EXPR_CONST, HEX_CONST, INT_CONST, NEG_CONST};
    // FLOAT_CONST is not generated by Crubit.
    expect_that!(INT_CONST!(), eq(42));
    expect_that!(HEX_CONST!(), eq(0x2A));
    expect_that!(NEG_CONST!(), eq(-42));
    expect_that!(EXPR_CONST!(), eq(43));
    expect_that!(CAST_CONST!(), eq(42));
}
